sys_variable_value.value:
(function execute(inputs, outputs) {

    var textValue = inputs.textToTranslate
    
    var payloadObject = {
        "target_lang": "en", 
        "text": textValue 
    };
    

    outputs.request_payload = JSON.stringify(payloadObject);
    
})(inputs, outputs);

